'use client';
import {useState,useEffect,useCallback,useMemo,useRef,type FormEvent} from 'react';
import {Ear,LayoutDashboard,Users,Headphones,Wrench,CalendarDays,Building2,ClipboardCheck,Package,Truck,Handshake,Layers,CreditCard,TrendingUp,MessageSquare,CheckSquare,ShieldCheck,Settings,BarChart3,Search,Plus,ArrowUpRight,ArrowRight,ChevronRight,Download,Clock,Check,AlertCircle,FileText,RefreshCw,LogOut,ExternalLink,Heart,Star,Activity,PanelLeft,Bell,LifeBuoy,Link2,MoreHorizontal,X,Send,Upload,CheckCircle2,Lock,Stethoscope} from 'lucide-react';
import {SidebarProvider,Sidebar,SidebarHeader,SidebarContent,SidebarFooter,SidebarGroup,SidebarGroupLabel,SidebarMenu,SidebarMenuItem,SidebarMenuButton,SidebarInset,SidebarTrigger,useSidebar} from '@/components/ui/sidebar';
import {Dialog,DialogContent,DialogHeader,DialogTitle,DialogDescription} from '@/components/ui/dialog';
