function PageHeading({section,description,actions}:{section:string;description?:string;actions?:React.ReactNode}){return <div className="page-heading"><div className="eyebrow">{modules[section]?.group||'HEARING WORKSPACE'}</div><div className="heading-row"><div><h1>{title(section)}</h1><p>{description||modules[section]?.description}</p></div><div className="heading-actions">{actions}</div></div></div>}
function RecordForm({form,setForm,records,save,busy,role}:{form:any;setForm:(f:any)=>void;records:CareRecord[];save:(k:string,d:Data,r?:CareRecord)=>Promise<void>;busy:boolean;role:string}){
 const [data,setData]=useState<Data>({}),[error,setError]=useState('');
 useEffect(()=>{if(!form)return;const mod=modules[form.kind];const d:Data={};for(const f of mod.fields){d[f.key]=form.record?.data[f.key]??(f.options?.[0]||((f.type==='date'&&['date','checkedAt'].includes(f.key))?today():f.type==='number'?f.min||0:''));}Object.assign(d,form.defaults||{});setData(d);setError('')},[form]);
 const mod=form?modules[form.kind]:null;
 return <Dialog open={!!form} onOpenChange={v=>!v&&setForm(null)}><DialogContent className="record-dialog"><DialogHeader><DialogTitle>{form?.record?'Edit':'Add'} {mod?.singular}</DialogTitle><DialogDescription>{mod?.description}</DialogDescription></DialogHeader>{mod&&<form className="record-form" onSubmit={async e=>{e.preventDefault();setError('');try{await save(form.kind,data,form.record)}catch(err){setError((err as Error).message)}}}><div className="form-grid">{mod.fields.map(f=>{const linked=records.filter(r=>r.kind===f.ref&&(f.ref!=='devices'||!data.patientId||r.data.patientId===data.patientId));const value=data[f.key];return <div className={cls('field',f.type==='textarea'&&'full-field')} key={f.key}><label htmlFor={'field-'+f.key}>{f.label}{f.required&&<span> *</span>}</label>{f.options||f.ref?<Pick id={'field-'+f.key} value={String(value??'')} onChange={v=>setData(d=>({...d,[f.key]:v,...(f.key==='patientId'&&mod.fields.some(x=>x.key==='deviceId')?{deviceId:''}:{})}))} options={f.options?f.options.map(v=>({value:v,label:v})):linked.map(r=>({value:r.id,label:labelOf(r)}))} placeholder={'Choose '+f.label.toLowerCase()}/>:f.type==='textarea'?<Textarea id={'field-'+f.key} value={String(value??'')} required={f.required} maxLength={6000} onChange={e=>setData(d=>({...d,[f.key]:e.target.value}))}/>:f.type==='boolean'?<Checkbox id={'field-'+f.key} checked={!!value} onCheckedChange={v=>setData(d=>({...d,[f.key]:!!v}))}/>:<Input id={'field-'+f.key} type={f.type||'text'} value={String(value??'')} required={f.required} min={f.min} max={f.max} step={f.type==='number'?'any':f.type==='datetime-local'?900:undefined} onChange={e=>setData(d=>({...d,[f.key]:e.target.value}))}/>} {f.hint&&<small>{f.hint}</small>}{f.ref&&!linked.length&&<small className="field-warning">Add a {modules[f.ref].singular} first.</small>}</div>})}</div>{error&&<p className="form-error" role="alert">{error}</p>}<div className="form-footer"><Button type="button" variant="outline" onClick={()=>setForm(null)}>Cancel</Button><Button disabled={busy}>{busy?'Saving…':form.record?'Save changes':`Create ${mod.singular}`}</Button></div></form>}</DialogContent></Dialog>
}
function MemberDialog({member,setMember,records,save}:{member:any;setMember:(m:any)=>void;records:CareRecord[];save:(m:any)=>Promise<void>}){const [d,setD]=useState<any>({}),[busy,setBusy]=useState(false),[error,setError]=useState('');useEffect(()=>{setD({name:member?.name||'',email:member?.email||'',role:member?.role||'coordinator',patientId:member?.patient_ids?JSON.parse(member.patient_ids)[0]||'':'',supplierId:member?.supplier_id||'',active:member?.active!==0});setError('')},[member]);return <Dialog open={!!member} onOpenChange={v=>!v&&setMember(null)}><DialogContent><DialogHeader><DialogTitle>{member?.id?'Manage access':'Add team or portal member'}</DialogTitle><DialogDescription>Members sign in with their own account. No email is sent.</DialogDescription></DialogHeader><form className="record-form" onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await save({id:member.id,name:d.name,email:d.email,role:d.role,patientIds:d.patientId?[d.patientId]:[],supplierId:d.supplierId,active:d.active})}catch(err){setError((err as Error).message)}finally{setBusy(false)}}}><label htmlFor="member-name">Name</label><Input id="member-name" value={d.name||''} required onChange={e=>setD({...d,name:e.target.value})}/><label htmlFor="member-email">Sign-in email</label><Input id="member-email" type="email" required value={d.email||''} readOnly={!!member?.id} onChange={e=>setD({...d,email:e.target.value})}/><label htmlFor="member-role">Role</label><Pick id="member-role" value={d.role} onChange={role=>setD({...d,role})} options={['admin','clinician','coordinator','supplier','patient','carer'].map(r=>({value:r,label:r[0].toUpperCase()+r.slice(1)}))}/>{['patient','carer'].includes(d.role)&&<><label htmlFor="member-patient">Linked patient</label><Pick id="member-patient" value={d.patientId} onChange={patientId=>setD({...d,patientId})} options={records.filter(r=>r.kind==='patients').map(r=>({value:r.id,label:labelOf(r)}))}/></>}{d.role==='supplier'&&<><label htmlFor="member-supplier">Linked supplier</label><Pick id="member-supplier" value={d.supplierId} onChange={supplierId=>setD({...d,supplierId})} options={records.filter(r=>r.kind==='suppliers').map(r=>({value:r.id,label:labelOf(r)}))}/></>}<label className="checkbox-label"><Checkbox checked={!!d.active} onCheckedChange={v=>setD({...d,active:!!v})}/>Access active</label>{error&&<p className="form-error">{error}</p>}<Button disabled={busy}>{busy?'Saving…':'Save access'}</Button></form></DialogContent></Dialog>}
function RevenueCalculator(){const [clinics,setClinics]=useState(10),[fee,setFee]=useState(300),[cost,setCost]=useState(120);return <section className="panel calculator"><div><span className="eyebrow">BUSINESS PLANNING</span><h2>Model your clinic service</h2><p>An illustrative forecast using your own assumptions.</p></div><div className="calculator-inputs"><label>Paying clinics<Input type="number" min="0" value={clinics} onChange={e=>setClinics(Math.max(0,Number(e.target.value)))}/></label><label>Monthly fee per clinic (£)<Input type="number" min="0" value={fee} onChange={e=>setFee(Math.max(0,Number(e.target.value)))}/></label><label>Monthly service cost per clinic (£)<Input type="number" min="0" value={cost} onChange={e=>setCost(Math.max(0,Number(e.target.value)))}/></label></div><div className="calculator-result"><div><span>Annual revenue</span><strong>{money(clinics*fee*12)}</strong></div><div><span>Annual contribution before overheads</span><strong>{money(clinics*(fee-cost)*12)}</strong></div></div></section>}
function download(content:string,name:string,type:string){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function calendarFile(r:CareRecord,byId:Map<string,CareRecord>){const escape=(s:unknown)=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,'\\$&');const start=String(r.data.start).replace(/[-:]/g,'')+'00';const d=new Date(String(r.data.start)+'Z');d.setUTCMinutes(d.getUTCMinutes()+Number(r.data.duration));const end=d.toISOString().slice(0,19).replace(/[-:]/g,'');const out=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Hearing//Care Calendar//EN','BEGIN:VEVENT',`UID:${r.id}@hearing`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART;TZID=Europe/London:${start}`,`DTEND;TZID=Europe/London:${end}`,`SUMMARY:${escape(r.data.name)}`,`LOCATION:${escape(r.data.location)}`,`DESCRIPTION:${escape('Appointment with '+r.data.clinician)}`,'END:VEVENT','END:VCALENDAR'].join('\r\n');download(out,'hearing-appointment.ics','text/calendar');toast.success('Calendar file downloaded')}
function invoiceFile(r:CareRecord,byId:Map<string,CareRecord>,clinic:string){const esc=(s:unknown)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));const html=`<!doctype html><html lang="en"><meta charset="utf-8"><title>${esc(r.data.name)}</title><style>body{font:16px Arial;margin:60px;color:#172742}h1{font-size:38px}header{display:flex;justify-content:space-between;border-bottom:2px solid #2659ef;padding-bottom:30px}section{margin:35px 0}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:18px;border-bottom:1px solid #ddd}button{padding:12px}@media print{button{display:none}}</style><header><h1>${esc(clinic)}</h1><div><h2>Invoice ${esc(r.data.name)}</h2><p>${esc(r.data.status)}</p></div></header><section>Bill to: <strong>${esc(byId.get(String(r.data.patientId))?.data.name)}</strong><p>Due: ${esc(r.data.due)}</p></section><table><tr><th>Description</th><th>Total payable</th></tr><tr><td>${esc(r.data.description)}</td><td>${esc(money(r.data.amount))}</td></tr></table><p>Payment reference: ${esc(r.data.paymentReference||r.data.name)}</p><p>Contact your clinic for payment instructions and any applicable tax breakdown.</p><button onclick="window.print()">Print / save as PDF</button></html>`;download(html,String(r.data.name).replace(/[^a-zA-Z0-9_-]/g,'_')+'.html','text/html');toast.success('Invoice downloaded — open it to print or save as PDF')}
